/**
 * Types describing the `usage.json` file that is generated by `scripts/generate-data.ts`
 * at build time from the raw `data.json` and that provides the data for the page.
 */

/**
 * The number of starts per month. The keys are in the form "YY-MM"
 */
export type MonthlyCounts = Record<string, number>;

/**
 * The usage of a single country
 */
export interface CountryUsage {
  /**
   * The ISO 3166-1 alpha-2 code of the country
   */
  code: string;

  /**
   * The human-readable name of the country
   */
  name: string;

  /**
   * The total number of starts in this country
   */
  total: number;

  byMonth: MonthlyCounts;
}

/**
 * The usage at a single place, which is the approximate location of a city
 */
export interface PlaceUsage {
  lat: number;
  lng: number;

  /**
   * The total number of starts at this place
   */
  total: number;

  byMonth: MonthlyCounts;
}

/**
 * The usage on a single day
 */
export interface DayUsage {
  /**
   * The day in the form "YY-MM-DD"
   */
  date: string;

  /**
   * The number of starts for each version. The order is the same as `UsageData.versions`
   */
  counts: number[];

  /**
   * The version that was released on this day, or `null` if there was no release
   */
  release: string | null;
}

export interface UsageData {
  /**
   * The list of all versions, starting with the empty string that represents builds
   * without a version number, followed by all versions from newest to oldest
   */
  versions: string[];

  countries: CountryUsage[];
  places: PlaceUsage[];

  /**
   * The usage per day, sorted chronologically
   */
  days: DayUsage[];

  /**
   * For each version, the number of times each profile has been started
   */
  profiles: Record<string, Record<string, number>>;
}
